function weeklyOutput(hoursPerWeek, fatigueSensitivity) {
  const penalty = Math.max(0, hoursPerWeek - 50);
  const output = hoursPerWeek - (fatigueSensitivity / 100) * penalty * penalty;
  return Math.max(0, output);
}

